import{_ as e,o,c as n,a5 as i}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"pinia","description":"vue3发布以后，pinia也随着诞生， 代替 Vuex 做状态管理，比较直观的好处就是： 不用在区分 同步调用 和 异步调用 了； store 的修改动作 action 作为常规函数调用，而不是使用 dispatch 方法或者是 commit 去调用； 当然最重要的还是对 TS。","frontmatter":{"title":"pinia","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"vue3发布以后，pinia也随着诞生， 代替 Vuex 做状态管理，比较直观的好处就是： 不用在区分 同步调用 和 异步调用 了； store 的修改动作 action 作为常规函数调用，而不是使用 dispatch 方法或者是 commit 去调用； 当然最重要的还是对 TS。","sidebarWeight":98,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/数据流/pinia/pinia.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/pinia/pinia.md","filePath":"posts/Vue系统教程/04-路由与状态管理/pinia/pinia.md"}'),p={name:"posts/Vue系统教程/04-路由与状态管理/pinia/pinia.md"};function r(u,t,a,s,c,l){return o(),n("div",null,[...t[0]||(t[0]=[i('<div><h1 id="pinia" tabindex="-1">pinia <a class="header-anchor" href="#pinia" aria-label="Permalink to &quot;pinia&quot;">​</a></h1><blockquote><p>本节目标：理解“pinia”的核心思路，并能把它用于实际开发或面试表达。 vue3发布以后，pinia也随着诞生， 代替 Vuex 做状态管理，比较直观的好处就是：</p></blockquote><ul><li>不用在区分 同步调用 和 异步调用 了；</li><li>store 的修改动作 action 作为常规函数调用，而不是使用 dispatch 方法或者是 commit 去调用；</li><li>当然最重要的还是对 TS 支持比较友好</li></ul><p>随着 Vue 3 的 Composition API 的推出，出现了一些新的状态管理库，例如 Pinia，它提供了一个更加简洁的 API 并充分利用了组合式 API 的特点。</p><p><strong>Pinia vs Vuex:</strong></p><ul><li>更简洁的API: Pinia 的 API 更简洁，更易于理解，尤其对于那些熟悉 Vue 3 的 Composition API 的开发者来说。</li><li>完全基于组合式API: 与 Vuex 的 mapGetters、mapActions 和 mapMutations 等辅助函数不同，Pinia 通过 Composition API 提供了更加直观的方式来访问状态、getters 和 actions。</li><li>Devtools 集成: Pinia 也与 Vue Devtools 完美集成，提供了对状态、actions 等的视图。</li></ul><p>如何使用 Pinia: 一、首先，你需要安装它： npm install @pinia/vue npm install @pinia/core</p><p>二、然后，设置 Pinia： main.js/main.ts import { createApp } from &#39;vue&#39; import { createPinia } from &#39;@pinia/vue&#39; import App from &#39;./App.vue&#39; const app = createApp(App) app.use(createPinia()) app.mount(&#39;#app&#39;)</p><p>三、接下来，创建你的第一个 store： stores/counter.js import { defineStore } from &#39;@pinia/core&#39; export const useCounterStore = defineStore({ id: &#39;counter&#39;, state: () =&gt; ({ count: 0 }), getters: { double: state =&gt; state.count * 2, expo: state =&gt; state.count ** 2, }, actions: { increment() { this.count++ } } })</p><p>四、现在，在你的组件中使用这个 store： YourComponent.vue &lt;template&gt; &lt;div&gt; &lt;p&gt;Count: {{ count }}&lt;/p&gt; &lt;p&gt;Double: {{ double }}&lt;/p&gt; &lt;p&gt;Expo: {{ expo }}&lt;/p&gt; &lt;button @click=&quot;increment&quot;&gt;Increment&lt;/button&gt; &lt;/div&gt; &lt;/template&gt; &lt;script&gt; import { useCounterStore } from &#39;@/stores/counter&#39; export default { setup() { const counter = useCounterStore() return { count: counter.count, double: counter.double, expo: counter.expo, increment: counter.increment, } } } &lt;/script&gt; 这只是一个简单的示例，但你可以看到 Pinia 的工作方式与 Vuex 有很大的不同，尤其是在其与组合式 API 的集成方面。如果你喜欢组合式 API 的工作方式，那么使用 Pinia 作为状态管理工具可能是一个很好的选择。</p><p>另外的使用方式： import { ref } from &quot;vue&quot;; import { defineStore } from &quot;pinia&quot;; export const useCounterStore = defineStore(&quot;counter&quot;, () =&gt; { const count = ref(0); function increment() { count.value++; } return { count, increment }; }); 相比组合式API，在不同组件中调用useCounterStore返回的store是同一个引用，而不是每次调用都创建一个新的引用；</p><p>在 Vue 3 的 Composition API 中，每次调用一个 ref 或 reactive 定义的 setup 函数或 composable 函数时，它都会返回一个新的引用。这意味着，如果两个组件都调用了相同的 composable 函数，那么这两个组件中的数据引用是彼此独立的。</p><p>而在 Pinia（或 Vuex）中，情况则不同。当你定义一个 store（如 useCounterStore）并在多个组件中使用时，你实际上是在访问同一个 store 的单一实例。这意味着所有使用这个 store 的组件都共享相同的数据状态。</p><p>举例说明： 使用 Composition API 的情况： function useCounter() { const count = ref(0); function increment() { count.value++; } return { count, increment }; } // 在 ComponentA 和 ComponentB 中都调用 useCounter // 这两个组件中的 count 是不同的引用，彼此独立。</p><p>使用 Pinia 的情况： export const useCounterStore = defineStore(&quot;counter&quot;, () =&gt; { const count = ref(0); function increment() { count.value++; } return { count, increment }; }); // 在 ComponentA 和 ComponentB 中都调用 useCounterStore // 这两个组件中的 count 是相同的引用，共享同一状态。 因此，如果你需要在多个组件之间共享和管理状态，Pinia 或 Vuex 这样的状态管理库是很有用的。</p></div>',1)])])}const f=e(p,[["render",r]]);export{d as __pageData,f as default};
